;; curriculum: Precalc (gr 11) — limits; prerequisites: series, sine
;; math target: a removable hole at x = c has the same left and right limit; the road stitches once both sides are visited.

app riya-level-limits "1.1.0"
"riya level 16 · The Limit — y = 0.6x + 3 with a removable hole at x = 2 — the road ends, then it stitches. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the hole, the ghost curve, and the one-sided approach stay visible. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaLimitsOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaLimitsBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaLimitsPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaLimitsFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaLimitsFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }
  type RiyaLimitsStar = {
    id : string!
    x : number!
    y : number!
    type : string!
  }
  type RiyaLimitsCurveSample = {
    x : number!
    y : number!
  }
  type RiyaLimitsCurve = {
    label : string
    color : string
    samples : [RiyaLimitsCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaLimitsGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaLimitsPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaLimitsLiftMod = {
    id : string!
    x0 : number!
    x1 : number!
    a : number!
    h : number!
    k : number!
  }

  entity RiyaLimitsState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaLimitsBody = { x: -5, y: 0.6, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    features : [RiyaLimitsStar] = []
    pickups : [RiyaLimitsPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaLimitsFx] = []
    celebrated : boolean = false
    visitedLeft : boolean = false
    visitedRight : boolean = false
    stitched : boolean = false
    zoneId : string = "limits"
    seq : number = 0
    lastText : string = ""
    platforms : [RiyaLimitsPlatform] = []
    curves : [RiyaLimitsCurve] = []
    guides : [RiyaLimitsGuide] = []
  }

  entity LimitsTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait LimitsBody = Body.traits.PlatformerBody -> RiyaLimitsState {
    events {
      STEER: LIMITS_STEER
      JUMP: LIMITS_LEAP
      PLACE: LIMITS_PLACE
      RESTART: LIMITS_RESTART
      CURVE_MOD_ADD: LIMITS_CURVE_MOD_ADD
      SET_TUNING: LIMITS_SET_TUNING
      SET_PLATFORMS: LIMITS_SET_PLATFORMS
      SET_SKATE_CURVE: LIMITS_SET_SKATE_CURVE
      BODY_JUMPED: LIMITS_JUMPED
      BODY_LANDED: LIMITS_LANDED
      BODY_HAZARD: LIMITS_HAZARD
      BODY_GOAL: LIMITS_GOAL
      BODY_FELL: LIMITS_FELL
      BODY_SKATE_START: LIMITS_SKATE_ON
      BODY_SKATE_END: LIMITS_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -5, y: 0.6, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -8
      xMax: 10
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait LimitsGate = Gate.traits.ObjectiveFlow -> RiyaLimitsState {
    events {
      PROGRESS: LIMITS_PROGRESS
      GAME_END: LIMITS_GAME_END
      RESTART: LIMITS_RESTART
    }
    config { running: true }
  }

  trait LimitsFx = Particles.traits.FxParticles -> RiyaLimitsState {
    events {
      BURST: LIMITS_BURST
    }
    config { running: true }
  }

  trait LimitsTutorialPreview -> LimitsTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait LimitsTutorial = Tutorial.traits.TutorialOverlay -> LimitsTutorialData {
    events {
      SHOW: LIMITS_TUTORIAL_SHOW
      TUTORIAL_DONE: LIMITS_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.LimitsTutorialPreview
      steps: [
        { id: "intro", title: "The Limit", body: "The graph y = 0.6x + 3 has a removable hole at x = 2. Approach from both sides; when the left and right heights agree, the road stitches itself." }
      ]
    }
  }

  trait LimitsPickup = Pickup.traits.Pickup -> RiyaLimitsState {
    events {
      PICKED: LIMITS_PICKED
      COLLECT: LIMITS_COLLECT
      PICKUP_SET_COMPLETED: LIMITS_PICKUP_SET_COMPLETED
      SET_FEATURES: LIMITS_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait LimitsLevelData -> @rebindable RiyaLimitsState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "limits"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          skateCurve: (array/map @config.skateCurve (fn p @p))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaLimitsPlatform]!
        stars : [RiyaLimitsPickup]!
        curveOverlay : [RiyaLimitsCurve]
        guides : [RiyaLimitsGuide]
        skateCurve : [RiyaLimitsCurveSample]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "The Limit"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 0.6x + 3"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "y = 0.6x + 3 has a removable hole at x = 2; the left and right branches meet at the same height, so the limit exists and the road can stitch"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = -0.6
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge (top of the l0 ground tile); the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 7.2
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge (top of the r2 ground tile); the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaLimitsPlatform] = [
        { id: "l0", x: -6, y: -2, width: 2, height: 1.4, type: "ground" }
        { id: "l1", x: -4, y: -2, width: 2, height: 2.6, type: "ground" }
        { id: "l2", x: -2, y: -2, width: 2, height: 3.8, type: "ground" }
        { id: "l3", x: 0, y: -2, width: 2, height: 5, type: "ground" }
        { id: "r0", x: 3, y: -2, width: 2, height: 6.8, type: "ground" }
        { id: "r1", x: 5, y: -2, width: 2, height: 8, type: "ground" }
        { id: "r2", x: 7, y: -2, width: 2, height: 9.2, type: "ground" }
      ]
        @label "Platforms"
        @description "Canonical terrain — seeds the body authority's collision AND the canvas bars via RIYA_LEVEL_DATA. Bars under the two solid branches of the graph; the gap at x = 2 is the removable discontinuity."
        @tier "domain"
      stars : [RiyaLimitsPickup] = [
        { id: "s1", x: -4, y: 1.4, kind: "star", glyph: "★", message: "" }
        { id: "s2", x: 5, y: 6.8, kind: "star", glyph: "★", message: "" }
        { id: "s3", x: 2, y: 5.7, kind: "star", glyph: "★", message: "" }
        { id: "lift", x: -3, y: 2.2, kind: "lift", glyph: "+k", message: "f(x)+2" }
