  trait RiyaLimitsGenre = Genre.traits.PlatformerPuzzle -> RiyaLimitsState {
    config {
      agencyTrait: @trait.LimitsBody
      challengeTrait: @trait.LimitsBody
      goalTrait: @trait.LimitsGate
      rewardTrait: @trait.LimitsPickup
      feedbackTrait: @trait.LimitsFx
    }
  }

  trait RiyaLimitsPlay -> @rebindable RiyaLimitsState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit LIMITS_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "LIMITS_LEFT", KeyA: "LIMITS_LEFT", ArrowRight: "LIMITS_RIGHT", KeyD: "LIMITS_RIGHT", ArrowUp: "LIMITS_JUMP", KeyW: "LIMITS_JUMP", Space: "LIMITS_JUMP" }
            keyUpMap: { ArrowLeft: "LIMITS_STOP", KeyA: "LIMITS_STOP", ArrowRight: "LIMITS_STOP", KeyD: "LIMITS_STOP" }
            guides: @entity.guides
            curves: (array/concat
              @entity.curves
              [ { label: (if @entity.stitched "" "limit path"), color: (if @entity.stitched "#38bdf8" "#94a3b8"), samples: [ { x: 1.8, y: 4.08 }, { x: 2, y: 4.2 }, { x: 2.2, y: 4.32 } ], dash: (if @entity.stitched null "dashed") } ])
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "lift") "#f472b6" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  [ { x: 2, y: 4.2, label: "", color: "#ef4444", radius: 7, style: "open" } ]
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "LIMITS_LEFT", right: "LIMITS_RIGHT", up: "LIMITS_JUMP" }, directionReleaseEvents: { left: "LIMITS_STOP", right: "LIMITS_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "limits")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit LIMITS_SET_PLATFORMS { platforms: @payload.platforms })
        (emit LIMITS_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit LIMITS_SET_FEATURES { features: @payload.stars })

      LIMITS_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LIMITS_STEER { dir: -1 })

      LIMITS_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LIMITS_STEER { dir: 1 })

      LIMITS_STOP -> idle when (== @entity.active true)
        (emit LIMITS_STEER { dir: 0 })

      LIMITS_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LIMITS_LEAP {})

      LIMITS_FELL -> idle when (== @entity.active true)
        (emit LIMITS_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit LIMITS_BURST { particles: (array/map [ "fx-limits-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.8, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })

      LIMITS_SKATE_ON -> idle when (== @entity.active true)
        (emit LIMITS_BURST { particles: (array/concat
          (array/map [ "skate" ] (fn _ { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "left limit = 4.2", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }))
          (array/map [ "fx-limits-skate" ] (fn fid { id: @fid, type: "info", x: @payload.x, z: (+ @payload.y 0.6), message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)), ttl: 4, maxTtl: 4, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }))
        ) })
      LIMITS_PICKED -> idle when (== @entity.active true)
        (emit LIMITS_BURST { particles: (array/map [ { id: (str/concat "fx-pickup-" @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: (if (== @payload.kind "lift") "+k" @payload.glyph), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.8, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" } ] (fn e @e)) })
      LIMITS_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit LIMITS_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      LIMITS_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit LIMITS_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 2, z: 7, y: 0, message: "left limit = right limit = stitched", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit LIMITS_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      LIMITS_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "limits" })

      LIMITS_TUTORIAL_DONE -> idle
        (emit LIMITS_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 2, z: 7, y: 0, message: "the graph has a hole at x = 2", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "LIMITS_LEFT", KeyA: "LIMITS_LEFT", ArrowRight: "LIMITS_RIGHT", KeyD: "LIMITS_RIGHT", ArrowUp: "LIMITS_JUMP", KeyW: "LIMITS_JUMP", Space: "LIMITS_JUMP" }
            keyUpMap: { ArrowLeft: "LIMITS_STOP", KeyA: "LIMITS_STOP", ArrowRight: "LIMITS_STOP", KeyD: "LIMITS_STOP" }
            guides: @entity.guides
            curves: (array/concat
              @entity.curves
              [ { label: (if @entity.stitched "" "limit path"), color: (if @entity.stitched "#38bdf8" "#94a3b8"), samples: [ { x: 1.8, y: 4.08 }, { x: 2, y: 4.2 }, { x: 2.2, y: 4.32 } ], dash: (if @entity.stitched null "dashed") } ])
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "lift") "#f472b6" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  [ { x: 2, y: 4.2, label: "", color: "#ef4444", radius: 7, style: "open" } ]
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      LIMITS_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      LIMITS_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      LIMITS_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      LIMITS_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (LIMITS_LEAP), which accepts it only while grounded."
        @tier "domain"
      LIMITS_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      LIMITS_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      LIMITS_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      LIMITS_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      LIMITS_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the graph — fires the equation fx burst."
        @tier "domain"
      LIMITS_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); carries kind so the board can apply boost effects like curve lifts."
        @tier "domain"
      LIMITS_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      LIMITS_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      LIMITS_SET_TUNING -> external {
        jumpStrength : number
        moveSpeed : number
        gravity : number
      }
        @description "Renamed SET_TUNING consumed by the platformer-body authority; live overrides for jump, speed, or gravity."
        @tier "domain"
      LIMITS_SET_PLATFORMS -> external {
        platforms : [RiyaLimitsPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      LIMITS_SET_SKATE_CURVE -> external {
        curve : [RiyaLimitsCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate rail."
        @tier "domain"
      LIMITS_SET_FEATURES -> external {
        features : [RiyaLimitsPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
      LIMITS_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      LIMITS_BURST -> external {
        particles : [RiyaLimitsFx]
      }
        @description "Particle batch spawned on star pickup, pit respawn, road stitching, or tutorial dismiss; fx-particles fades it."
        @tier "domain"
      LIMITS_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted when a star is collected or the set completes; the objective-flow gate resolves won from it."
        @tier "domain"
      LIMITS_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
    }

    listens {
      LIMITS_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
