      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow."
        @tier "presentation"
      fxPresets : [RiyaLimitsFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      conceptText : string = "y = 0.6x + 3 has a removable hole at x = 2; the left and right branches meet at the same height, so the limit exists and the road can stitch"
        @label "Concept Text"
        @description "The world's one math idea — metadata for the picker/factory, not rendered in-game."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      terrainColor : string = "#78716c"
        @label "Terrain Color"
        @description "Bar color for the ground/platform bars."
        @tier "presentation"
      xMin : number = -8
        @label "X Min"
        @description "Left edge of the visible math window."
        @tier "presentation"
      xMax : number = 10
        @label "X Max"
        @description "Right edge of the visible math window."
        @tier "presentation"
      yMin : number = -2
        @label "Y Min"
        @description "Bottom edge of the visible math window."
        @tier "presentation"
      yMax : number = 10
        @label "Y Max"
        @description "Top edge of the visible math window."
        @tier "presentation"
      width : number = 800
        @label "Canvas Width"
        @description "math-canvas display width in px."
        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
        @description "math-canvas display height in px."
        @tier "presentation"
    }
  }

  trait LimitsChallenge -> @rebindable RiyaLimitsState [game-core, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.visitedLeft false)
        (set @entity.visitedRight false)
        (set @entity.stitched false)

      LIMITS_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "lift")
          (do
            (emit LIMITS_CURVE_MOD_ADD { x0: -6, x1: 1.8, a: 1, h: 0, k: 2 })
            (emit LIMITS_BURST { particles: (array/map [ "lift" ] (fn _ { id: "narrative-lift", type: "narrative", x: @payload.x, z: (+ @payload.y 1.2), y: 0, message: "f(x)+2", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 })) }))
          null)
    }

    ticks {
      stitchTick every 100ms when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (< @entity.body.x @config.visitLeftX) (set @entity.visitedLeft true) null)
        (if (> @entity.body.x @config.visitRightX) (set @entity.visitedRight true) null)
        (if (and @entity.visitedLeft (and @entity.visitedRight (== @entity.stitched false)))
          (do
            (set @entity.stitched true)
            (emit LIMITS_CURVE_MOD_ADD { x0: 1.5, x1: 2.5, a: 1, h: 0, k: 0 })
            (emit LIMITS_BURST { particles: (array/map [ "stitch" ] (fn _ { id: "narrative-stitch", type: "narrative", x: 2, z: 5, y: 0, message: "right limit = 4.2", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 })) }))
          null)
    }

    emits {
      LIMITS_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Curve mod consumed by the platformer-body authority; the +k lift raises the left branch, the stitch reveals the limit path once both sides are visited."
        @tier "domain"
      LIMITS_BURST -> external {
        particles : [RiyaLimitsFx]
      }
        @description "Narrative bursts for the lift pad and the stitch beat; fx-particles fades them."
        @tier "domain"
    }

    listens {
      LIMITS_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "limits"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
      visitLeftX : number = 1.5
        @label "Left-Visit Threshold X"
        @description "Body x below which the left branch counts as visited (zone-local standalone; the open world overrides with world coordinates)."
        @tier "domain"
      visitRightX : number = 2.5
        @label "Right-Visit Threshold X"
        @description "Body x above which the right branch counts as visited (zone-local standalone; the open world overrides with world coordinates)."
        @tier "domain"
    }
  }

  trait RiyaLimitsClear -> @rebindable RiyaLimitsState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "LIMITS_NEXT", variant: "primary" } ]
        })

      LIMITS_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      LIMITS_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-limits"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Limit clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "The left road and the right road meet at the same height — the limit stitches the gap."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-limits" as RiyaLimitsPage -> LimitsLevelData, LimitsBody, LimitsGate, LimitsFx, LimitsPickup, LimitsTutorial, RiyaLimitsGenre, RiyaLimitsPlay, LimitsChallenge, RiyaLimitsClear
}
